/* @lc app=leetcode id=2484 lang=kotlin */ class Solution { fun countPalindromes(s: String): Int = s.length.let { n -> Array(n) { IntArray(100) }.let { pre -> Array(n) { IntArray(100) }.let { suf -> IntArray(10).let { c1 -> (0 until n).forEach { i -> (if (i > 0) pre[i].apply { (0 until 100).forEach { x -> this[x] = pre[i - 1][x] + if (x % 10 == s[i] - '0') c1[x / 10] else 0 } } else pre[i].apply { (0 until 100).forEach { x -> this[x] = 0 } }).also { c1[s[i] - '0']++ } }.let { IntArray(10).let { c2 -> (n - 1 downTo 0).forEach { i -> (if (i < n - 1) suf[i].apply { (0 until 100).forEach { x -> this[x] = suf[i + 1][x] + if (x % 10 == s[i] - '0') c2[x / 10] else 0 } } else suf[i].apply { (0 until 100).forEach { x -> this[x] = 0 } }).also { c2[s[i] - '0']++ } }.let { (2 until n - 2).fold(0L) { acc, i -> (acc + (0 until 100).sumOf { x -> pre[i - 1][x].toLong() * suf[i + 1][x] }) % 1000000007 }.toInt() } } } } } } } }